        <span class="entry-card-title">${item.title || 'Untitled Role'} at ${item.company || 'Company'}</span>
        <div class="entry-actions">
          <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, -1)"><i class="fa-solid fa-arrow-up"></i></button>
          <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, 1)"><i class="fa-solid fa-arrow-down"></i></button>
          <button class="btn btn-danger btn-sm" onclick="removeItem('experience', '${item.id}')"><i class="fa-solid fa-trash"></i></button>
        </div>
      </div>
      <div class="form-group">
        <label>Job Title</label>
        <input type="text" value="${escapeAttr(item.title)}" oninput="updateItemField('experience', '${item.id}', 'title', this.value)"/>
      </div>
      <div class="form-row">
        <div class="form-group">
          <label>Company Name</label>
          <input type="text" value="${escapeAttr(item.company)}" oninput="updateItemField('experience', '${item.id}', 'company', this.value)"/>
        </div>
        <div class="form-group">
          <label>Location</label>
          <input type="text" value="${escapeAttr(item.location)}" oninput="updateItemField('experience', '${item.id}', 'location', this.value)"/>
        </div>
      </div>
      <div class="form-row">
        <div class="form-group">
          <label>Start Date</label>
          <input type="month" value="${item.startDate || ''}" onchange="updateItemField('experience', '${item.id}', 'startDate', this.value)"/>
        </div>
        <div class="form-group">
          <label>End Date</label>
          <input type="month" value="${item.endDate || ''}" ${item.current ? 'disabled' : ''} onchange="updateItemField('experience', '${item.id}', 'endDate', this.value)"/>
        </div>
      </div>
      <div class="checkbox-group">
        <input type="checkbox" id="exp-curr-${item.id}" ${item.current ? 'checked' : ''} onchange="updateItemField('experience', '${item.id}', 'current', this.checked)"/>
