// Render Custom Sections
function renderCustomSectionsList() {
  const container = document.getElementById('custom-sections-list');
  container.innerHTML = '';
  resumeData.customSections.forEach((sec, secIndex) => {
    const card = document.createElement('div');
    card.className = 'entry-card';
    card.innerHTML = `
      <div class="entry-card-header">
        <span class="entry-card-title">${sec.heading || 'Custom Section'}</span>
        <div class="entry-actions">
          <button class="btn btn-danger btn-sm" onclick="removeCustomSection('${sec.id}')"><i class="fa-solid fa-trash"></i></button>
        </div>
      </div>
      <div class="form-group">
        <label>Section Heading Title</label>
        <input type="text" value="${escapeAttr(sec.heading)}" oninput="updateCustomHeading('${sec.id}', this.value)"/>
      </div>
      <div style="margin-top:0.75rem;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:0.5rem;">
          <label style="margin:0;">Section Items</label>
          <button class="btn btn-outline btn-sm" onclick="addCustomItem('${sec.id}')"><i class="fa-solid fa-plus"></i> Add Item</button>
        </div>
        <div id="custom-items-${sec.id}"></div>
      </div>
    `;
    container.appendChild(card);

    // Render nested items
    const itemContainer = card.querySelector(`#custom-items-${sec.id}`);
    sec.items.forEach((item) => {
      const itemBox = document.createElement('div');
      itemBox.style.cssText = 'border: 1px dashed #cbd5e1; padding: 0.75rem; border-radius: 0.375rem; margin-bottom: 0.5rem; background:#fff;';
      itemBox.innerHTML = `
        <div style="text-align:right; margin-bottom:0.25rem;">
          <button class="btn btn-danger btn-sm" onclick="removeCustomItem('${sec.id}', '${item.id}')"><i class="fa-solid fa-xmark"></i></button>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Title</label>
            <input type="text" value="${escapeAttr(item.title)}" oninput="updateCustomItemField('${sec.id}', '${item.id}', 'title', this.value)"/>
          </div>
          <div class="form-group">
            <label>Subtitle / Organization</label>
            <input type="text" value="${escapeAttr(item.subtitle)}" oninput="updateCustomItemField('${sec.id}', '${item.id}', 'subtitle', this.value)"/>
          </div>
        </div>
        <div class="form-group">
          <label>Date / Period</label>
          <input type="text" value="${escapeAttr(item.date)}" oninput="updateCustomItemField('${sec.id}', '${item.id}', 'date', this.value)"/>
        </div>
        <div class="form-group">
          <label>Description</label>
          <textarea rows="2" oninput="updateCustomItemField('${sec.id}', '${item.id}', 'description', this.value)">${item.description || ''}</textarea>
        </div>
      `;
      itemContainer.appendChild(itemBox);
    });
  });
}

function addCustomSection() {
  resumeData.customSections.push({
    id: generateId(),
    heading: 'Custom Section',
    items: []
  });
  renderCustomSectionsList();
  saveToLocalStorage();
  renderResume();
}

function removeCustomSection(secId) {
  resumeData.customSections = resumeData.customSections.filter(s => s.id !== secId);
  renderCustomSectionsList();
  saveToLocalStorage();
  renderResume();
}

function updateCustomHeading(secId, val) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) sec.heading = val;
  saveToLocalStorage();
  renderResume();
}

function addCustomItem(secId) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    sec.items.push({
      id: generateId(),
      title: '',
      subtitle: '',
      date: '',
      description: ''
    });
    renderCustomSectionsList();
    saveToLocalStorage();
    renderResume();
  }
}

function removeCustomItem(secId, itemId) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    sec.items = sec.items.filter(i => i.id !== itemId);
    renderCustomSectionsList();
    saveToLocalStorage();
    renderResume();
  }
}

function updateCustomItemField(secId, itemId, field, val) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    const item = sec.items.find(i => i.id === itemId);
    if (item) item[field] = val;
    saveToLocalStorage();
    renderResume();
  }
}

// Generic list helpers
function renderAllLists() {
  renderExperienceList();
  renderEducationList();
  renderSkillsList();
  renderProjectsList();
  renderLanguagesList();
  renderCertificationsList();
  renderSocialsList();
  renderReferencesList();
  renderHobbiesList();
  renderCustomSectionsList();
}

function updateItemField(category, id, field, val) {
  const item = resumeData[category].find(i => i.id === id);
  if (item) {
    item[field] = val;
    saveToLocalStorage();
    renderResume();
  }
}

function removeItem(category, id) {
  resumeData[category] = resumeData[category].filter(i => i.id !== id);
  renderAllLists();
  saveToLocalStorage();
  renderResume();
}

function moveItem(category, index, direction) {
  const arr = resumeData[category];
  const targetIndex = index + direction;
  if (targetIndex >= 0 && targetIndex < arr.length) {
    const temp = arr[index];
    arr[index] = arr[targetIndex];
    arr[targetIndex] = temp;
    renderAllLists();
    saveToLocalStorage();
    renderResume();
  }
}

function escapeAttr(str) {
  if (!str) return '';
  return str.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function formatDate(dateStr) {
  if (!dateStr) return '';
  const [year, month] = dateStr.split('-');
  if (!year) return dateStr;
  if (!month) return year;
  const date = new Date(year, month - 1);
  return date.toLocaleString('default', { month: 'short' }) + ' ' + year;
}

// ==========================================
// MAIN RESUME RENDER ENGINE
// ==========================================
function renderResume() {
  const container = document.getElementById('resume-preview');
  const settings = resumeData.settings;
  const p = resumeData.personal;

  // Calculate Padding based on margin setting
  let paddingMap = { compact: '1.5rem', normal: '2.5rem', spacious: '3.5rem' };
  const paddingVal = paddingMap[settings.margin] || '2.5rem';

  // Apply root inline style settings to preview paper
  container.style.fontFamily = `'${settings.fontFamily}', sans-serif`;
  container.style.fontSize = settings.fontSize || '14px';
  container.style.setProperty('--accent-color', settings.accentColor || '#2563eb');

  const template = settings.template || 'modern';

  let html = '';

  if (template === 'modern') {
    html = renderModernTemplate(p, paddingVal);
  } else if (template === 'classic') {
    html = renderClassicTemplate(p, paddingVal);
  } else if (template === 'minimal') {
    html = renderMinimalTemplate(p, paddingVal);
  } else if (template === 'creative') {
    html = renderCreativeTemplate(p, paddingVal);
  } else if (template === 'compact') {
    html = renderCompactTemplate(p, paddingVal);
  }

  container.innerHTML = html;
}

